mapper.select:
select COALESCE(sum(points), 0)
from points_record
where user_id = #{userId}
  and type = #{type}
  and create_time >= #{begin}
  and create_time <= #{end}

select COALESCE(sum(points), 0)
from points_record
where user_id = #{userId}
  and create_time >= #{begin}
  and create_time <= #{end}

select
       sum(points) as points,
       type
from points_record
where user_id = #{userId}
  and create_time >= #{begin}
  and create_time <= #{end}
group by  type

select *
from points_record
where create_time >= #{beginTime}
  and create_time <= #{endTime} limit #{offset}
    , #{pageSize}
order by create_time asc

select COALESCE(sum(points), 0)
from ${tableName}
where user_id = #{userId}
  and create_time >= #{begin}
  and create_time <= #{end}
